BEGIN;
CREATE TABLE conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid NOT NULL REFERENCES leads(id) ON DELETE CASCADE,direction text NOT NULL CHECK(direction IN('client','jawad','system')),telegram_message_id bigint,body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,lead_id uuid REFERENCES leads(id),job_id uuid REFERENCES jobs(id),recipient_chat_id bigint NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'queued',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE capacity_settings(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),maximum_active_quick_fixes integer NOT NULL DEFAULT 2,maximum_rescue_jobs integer NOT NULL DEFAULT 1,pause_checkout boolean NOT NULL DEFAULT false,next_available_date date,working_hours jsonb NOT NULL DEFAULT '{}',away_mode boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO capacity_settings(singleton) VALUES(true) ON CONFLICT DO NOTHING;
CREATE TABLE system_settings(key text PRIMARY KEY,value jsonb NOT NULL,sensitive boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE testimonial_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL UNIQUE REFERENCES jobs(id),status text NOT NULL DEFAULT 'requested',requested_at timestamptz NOT NULL DEFAULT now(),response text,permission_to_publish boolean NOT NULL DEFAULT false);
CREATE TABLE deletion_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),telegram_user_id bigint,email text,status text NOT NULL DEFAULT 'open',requested_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,notes text,CHECK(telegram_user_id IS NOT NULL OR email IS NOT NULL));
CREATE TABLE backup_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),started_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,status text NOT NULL,location_reference text NOT NULL,restore_tested_at timestamptz,notes text);
CREATE INDEX conversations_lead_idx ON conversations(lead_id,created_at);CREATE INDEX notifications_due_idx ON notifications(status,next_attempt_at);CREATE INDEX deletion_status_idx ON deletion_requests(status,requested_at);
COMMIT;
